import React, { useEffect, useState } from 'react';
import axios from 'axios';

// Updated image links (The Rubik's cube is gone!)
const medicineImages = {
  "Paracetamol": "https://images.unsplash.com/photo-1607619056574-7b8d3ee536b2?w=400&q=80",
  "Amoxicillin": "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=400&q=80",
  "Vitamin C": "https://images.unsplash.com/photo-1582436855071-77bba6632402?w=400&q=80" 
};

const defaultImage = "https://images.unsplash.com/photo-1550572017-ed3c2df28330?w=400&q=80";

function MedicinesList({ addToCart }) {
  const [medicines, setMedicines] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    axios.get('http://127.0.0.1:5000/api/medicines')
      .then(res => {
        setMedicines(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setError("Could not connect to the backend server.");
        setLoading(false);
      });
  }, []);

  if (loading) return <div className="text-center mt-20 text-xl font-bold">Loading medicines...</div>;
  if (error) return <div className="text-center mt-20 text-xl font-bold text-red-500">{error}</div>;

  return (
    <div className="w-full">
      {/* 1. The Hero Banner Section */}
      <div className="bg-blue-50 py-16 px-4 mb-12 text-center border-b border-blue-100">
        <h1 className="text-4xl md:text-5xl font-extrabold text-blue-800 mb-4 tracking-tight">
          Welcome to HealthPlus Pharmacy
        </h1>
        <p className="text-lg md:text-xl text-gray-600 max-w-2xl mx-auto">
          Your trusted neighborhood pharmacy, now online. Browse our top-quality medicines and wellness products delivered straight to your door.
        </p>
      </div>

      {/* 2. The Products Section */}
      <div className="max-w-6xl mx-auto px-4 mb-20">
        <div className="flex justify-between items-center mb-8 border-b pb-4">
          <h2 className="text-3xl font-bold text-gray-800">Featured Products</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {medicines.map(med => (
            <div key={med.id} className="bg-white p-6 rounded-2xl shadow-md border border-gray-100 flex flex-col items-center hover:shadow-2xl hover:-translate-y-1 transition-all duration-300">
              <img 
                src={medicineImages[med.name] || defaultImage} 
                alt={med.name} 
                className="w-48 h-48 object-cover mb-6 rounded-xl shadow-sm border border-gray-50" 
              />
              <h3 className="text-2xl font-bold text-gray-800 w-full text-left">{med.name}</h3>
              <p className="text-gray-500 text-sm text-left my-2 h-10 w-full">{med.description}</p>
              
              <div className="w-full flex justify-between items-center mt-4">
                <span className="text-3xl font-extrabold text-blue-600">${med.price}</span>
                <button 
                  onClick={() => addToCart(med)}
                  className="bg-blue-600 text-white px-6 py-2.5 rounded-full hover:bg-blue-700 transition-colors font-bold shadow-md active:transform active:scale-95"
                >
                  Add to Cart
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default MedicinesList;
